INSERT INTO unspoken (body, relate_count, hug_count, created_at) VALUES
($ltr$gw anak pertama dari tiga, dan sejak umur 12 gw udah jadi ibu kedua di rumah ini. nyuapin adek, nemenin belajar, bohong ke tukang tagih pas mama lagi ga ada di rumah... ga ada yang pernah nanya gw capek apa nggak. sekali gw nangis di dapur mama malah bilang 'kamu tuh kakak, harus kuat'. gw ga pernah ngerasain jadi anak. gw langsung disuruh jadi orang tua sebelum gw sempet ngerti caranya dijagain.$ltr$, 137, 88, now() - interval '24 minutes'),
($ltr$ranking 3 sekelas, papa cuma nyeletuk 'kok bukan satu'. adek ranking 10 malah dibeliin sepeda katanya udah usaha. aku ga pernah ngerti standarnya apa sih sebenernya. tiap bawa piala pulang rasanya kayak cuma nambahin daftar hal yang harusnya lebih bagus lagi. capek jadi anak yang bagusnya ga pernah cukup buat sekali aja diliat bener bener.$ltr$, 149, 54, now() - interval '100 minutes'),
($ltr$voicenote terakhir dari bapak masih ada di hp aku, isinya cuma 'nak, udah makan?' dan waktu itu aku cuma baca doang, ga aku bales karena lagi sibuk kerja. dua hari abis itu bapak pergi. sekarang aku muterin voicenote itu tiap malem cuma biar denger suaranya, dan tiap kali aku pengen ngetik 'udah pak, bapak juga makan ya, aku sayang bapak'... tapi udah ga ada yang bakal baca. aku ga pernah sekalipun bilang sayang ke dia pas dia masih bisa denger.$ltr$, 61, 124, now() - interval '122 minutes'),
($ltr$udah 4 tahun aku sama dia dan mama masih rutin nanya kapan aku bawa 'cewek' ke rumah. every family dinner mama cerita anak temennya yang baru nikah, and i just nod sambil mikir kalo aku jujur sekarang, apa aku masih punya rumah buat pulang. i love them too much to risk it, jadi aku milih ilang pelan pelan aja, tetep jadi anak yang mereka kira mereka kenal.$ltr$, 73, 96, now() - interval '230 minutes'),
($ltr$semua sepupu jadi dokter, insinyur, apapun yang enak dipamerin pas arisan. i dropped out and now i work a job mama bingung gimana jelasinnya ke tante tante. she never says i'm a disappointment out loud, tapi cara dia buru buru ganti topik pas ada yang nanya soal aku tuh udah cukup jelas. i became the kid you just don't bring up anymore.$ltr$, 88, 67, now() - interval '280 minutes'),
($ltr$my brother got a standing ovation for basically existing and i got a nod for making the dean's list. i stopped telling them my good news because the silence right after is somehow worse than just not saying anything at all. i'm 27 and i still catch myself doing things just to check if this is the one that finally makes them proud. it never is. it's never gonna be.$ltr$, 112, 71, now() - interval '414 minutes'),
($ltr$i figured out how to do my own taxes, patch up my own heartbreaks, move to a new city alone, all without calling home because i learned real early that no one would pick up in the way i needed them to. mom asks why i'm 'so distant' now. i'm not distant. i just stopped waiting by a phone that never rang and taught myself to need nothing from anybody. she raised a kid who physically cannot ask her for help and she has no clue she's the reason.$ltr$, 118, 93, now() - interval '488 minutes'),
($ltr$aku masih nyimpen voicemail kamu yang bilang 'ma, nanti aku telpon lagi ya'. udah dua tahun, dan itu satu satunya cara aku masih bisa denger suara kamu... tiap malem aku puterin, cuma biar ada yang ngomong ke aku pake suara itu lagi.$ltr$, 34, 119, now() - interval '644 minutes'),
($ltr$dulu tiap dia minta gw temenin main bola sore, gw selalu bilang 'besok ya nak, papa capek'. dan besok itu ga pernah beneran dateng, keburu dia gede. sekarang dia 25, ngomong sama gw sopan kayak sama bos kantor. gw kasih dia semua yang gw ga pernah punya waktu kecil, tapi ternyata gw ngambil satu satunya yang dia butuhin, yaitu gw sendiri.$ltr$, 58, 79, now() - interval '739 minutes'),
($ltr$waktu dia kelas 5 dia pengen banget sepatu yang temen temennya pada punya. aku cuma sanggup beliin yang KW di pasar, dan dia pakenya tanpa ngeluh sedikitpun. tapi aku sempet liat matanya pas ada yang ngatain sepatunya di depan kelas. sampe sekarang tiap inget itu dadaku masih sakit. aku banting tulang siang malem tapi ga pernah cukup buat kamu nak, maaf ya, bukan aku ga mau.$ltr$, 47, 108, now() - interval '916 minutes'),
($ltr$terakhir kali dia nelpon tiga bulan lalu, itu pun cuma buat minta nomor rekening. gw simpen semua chat dari dia yang isinya cuma 'iya', 'ok', 'nanti gw kabarin', gw baca ulang kayak itu barang berharga. gw sampe sekarang ga tau salah gw apa sampe anak sendiri ngomong ke gw kayak ke orang asing. dan gw ga berani nanya, takut jawabannya bikin gw makin ngerti.$ltr$, 41, 86, now() - interval '1032 minutes'),
($ltr$dia udah tiga tahun di melbourne dan tiap video call dia selalu bilang 'i'm good ma, don't worry'. tapi aku denger dari suaranya dia capek, homesick, cuma ga mau bikin aku khawatir. aku pengen banget bilang 'pulang aja nak' tapi aku tau itu selfish, dunianya udah disana sekarang. jadi aku cuma bilang 'ok, jaga kesehatan ya', terus baru nangis pas kameranya udah aku matiin.$ltr$, 52, 74, now() - interval '1228 minutes'),
($ltr$hari dia pindah kos aku bantuin angkat kardus sambil ketawa ketawa, terus pas mobilnya jalan aku masih senyum sampe dia ga keliatan lagi. balik ke rumah, kamarnya kosong, lampunya masih nyala, dan aku baru nangis di situ, di lantai, kayak orang ilang akal. delapan belas tahun rasanya cuma satu tarikan napas. nobody warns you that the whole point of raising them is teaching them to leave.$ltr$, 44, 81, now() - interval '1362 minutes'),
($ltr$i got diagnosed two months ago and i still haven't told my kids. they think the tiredness is just work. every sunday dinner i put on the whole show, cook their favorites, laugh at the dumb jokes, and the second they drive off i just sit in the car in the garage because i don't have the energy to walk back into the house. i've been their strong one their entire lives. i genuinely don't know how to be the one who needs them now.$ltr$, 38, 116, now() - interval '1577 minutes'),
($ltr$i raised my daughter the exact way my father raised me. cold, 'toughen up', never once said i love you because his father never did. she's 30 now and she still flinches a little when i hug her, because for 18 years i never reached out first. i broke something in her i can't even put a name to, and she's out there paying for a mistake that was never hers. i really thought i was making her strong. turns out i was just making her into me.$ltr$, 43, 77, now() - interval '1729 minutes'),
($ltr$kita tidur di ranjang yang sama tapi udah lama aku ga tau lagi dia mikirin apa. tadi malem aku cerita hari aku jelek banget di kantor, dia cuma bilang "oh" sambil terus scroll hp. aku diem aja. terus aku sadar aku udah lupa kapan terakhir kita ketawa bareng. dulu dia yang paling ngerti aku, sekarang dia kayak orang yang cuma numpang tinggal di rumahku. aku ga benci dia, itu yang paling nyakitin sih... aku cuma ngerasa sendirian justru pas dia lagi ada di sebelah.$ltr$, 128, 69, now() - interval '1961 minutes'),
($ltr$aku masih nyimpen foto usg-nya di laci, cuma titik kecil di minggu ke 11. tiap orang nanya kapan punya anak aku senyum terus jawab "belum rejeki". padahal aku udah kasih dia nama diem-diem, dan aku masih inget tanggalnya tiap bulan sampe sekarang.$ltr$, 29, 127, now() - interval '2131 minutes'),
($ltr$udah bertahun-tahun gw jadi menantu tapi di rumah mertua gw tetep kayak tamu. mama mertua selalu muji masakan adik iparnya tepat di depan gw, tiap lebaran gw yang nyuci semua piring sendirian di dapur sementara yang lain ngobrol di ruang tamu. suami gw? diem aja, katanya "namanya juga mama, sabar." gw nangis di kamar mandi bentar terus balik lagi pura-pura ga kenapa-napa. gw capek banget jadi orang yang harus selalu ngalah.$ltr$, 96, 58, now() - interval '2379 minutes'),
($ltr$nobody tells you how lonely 3am is when you're the only one awake feeding a baby while your husband sleeps through all of it. i love her so much it scares me but sometimes i just sit there in the dark and cry while she drinks and i don't even know why. i haven't showered in two days. i keep smiling in the photos i send to the family group chat. i feel like the woman i used to be disappeared the day she was born and literally nobody noticed she's gone.$ltr$, 64, 111, now() - interval '2565 minutes'),
($ltr$kadang aku bener-bener lupa aku dulu orangnya kayak gimana sebelum jadi "istri" sama "mama". dulu aku suka nge-dance, punya temen rame, ngerjain hal yang aku suka tanpa mikir. sekarang namaku cuma "mamanya X" di grup wa sekolah. i opened my closet yesterday and none of those clothes fit the person i am now, i just stood there like... who even am i. semua orang butuh aku tapi ga ada satu pun yang pernah nanya aku baik-baik aja apa engga.$ltr$, 103, 72, now() - interval '2830 minutes'),
($ltr$i cooked for four people tonight and cleaned everything after and nobody even looked up from their phones to say makasih. kemaren ulang tahunku dan yang inget cuma reminder facebook. i've basically become the furniture in my own house, ada tapi ga keliatan, sampai piring kotor numpuk baru aku dicariin.$ltr$, 91, 63, now() - interval '3032 minutes'),
($ltr$gw dulu kerja di firma, lagi diproses buat promosi, terus gw hamil dan semua orang bilang "keluarga nomor satu" jadi gw resign. sekarang tiap liat temen-temen gw naik jabatan di linkedin gw langsung close app-nya. i don't regret my kids, i swear i don't. tapi ada bagian dari gw yang mati pelan-pelan tiap hari dan gw ga bisa cerita ke siapa-siapa karena katanya gw harusnya bersyukur. sometimes i just sit in the parking lot a few extra minutes, alone, before i walk back in and become mom again.$ltr$, 76, 82, now() - interval '3312 minutes'),
($ltr$gaji gw telat lagi bulan ini dan gw belum berani bilang ke istri. tadi malem dia nanya bisa ga anak les tambahan, gw cuma senyum, 'nanti kita atur ya' padahal rekening tinggal ratusan ribu. yang dia ga tau, gw udah di-PHK tiga minggu lalu. tiap pagi gw tetep pake kemeja, cium keningnya, terus nyari lowongan di warkop sampe sore biar keliatan pulang kerja normal. gw ga tau harus jadi sekuat apa lagi sebelum semuanya ketauan...$ltr$, 54, 101, now() - interval '3530 minutes'),
($ltr$bapak meninggal minggu lalu dan aku ga nangis sedikit pun di pemakaman, semua orang bilang aku anak yang kuat. padahal tiga puluh tahun aku cuma nungguin satu kalimat dari dia yang ga pernah dateng, 'bapak bangga sama kamu'. kerja mati-matian, ikut ini itu, cuma biar dia noleh sekali aja. kursinya di ruang tamu masih ada. dan aku baru bisa nangis kemarin, pas ga sengaja nyium bantalnya yang masih bau minyak angin...$ltr$, 49, 122, now() - interval '3825 minutes'),
($ltr$terakhir kali gw nangis di depan orang umur 9 tahun, bokap narik kerah baju gw, 'cowok ga boleh cengeng'. sekarang gw 34, nyokap di ICU, dan gw berdiri di lorong rumah sakit gigit lengan sendiri biar ga ada suara. badannya beneran lupa caranya. yaudah gw telen aja, kayak biasa.$ltr$, 57, 113, now() - interval '4058 minutes'),
($ltr$she moved out on a tuesday and took the good pillows. i still sleep on my side of the bed like someone's on the other. papers have been signed four months and i haven't told my parents, every sunday call i just say 'she's busy, she says hi'. her number is still saved as 'home'. i don't know when i'm gonna change it. maybe i don't want to...$ltr$, 47, 89, now() - interval '4297 minutes'),
($ltr$everyone thinks i'm the funny one. i keep the whole group chat laughing and then i put the phone face down and stare at the ceiling for like two hours. when they ask how i'm doing i say 'living the dream man' and they believe me every single time. that's the part that scares me tbh. how easy it is. how nobody's ever checked twice.$ltr$, 121, 94, now() - interval '4615 minutes'),
($ltr$i'm the oldest son so i carried the casket, i handled the money, i sat with mom while she fell apart and said 'i got this'. nobody ever asked who i go to. the answer is nobody. i cried once in a parking garage last month and a stranger knocked on my window to ask if i was okay, i said yeah man just yawning. i've been holding everyone up so long i forgot i'm allowed to fall too.$ltr$, 108, 87, now() - interval '4869 minutes'),
($ltr$bokap gw ga pernah bilang 'sayang kamu', sekali pun ga pernah, katanya 'udah makan?' itu udah bahasa cintanya. sekarang gw jadi ayah, anak gw meluk gw tiap pagi dan gw... freeze. i don't know how to hug back, badan gw kaku, like there's no template for it in my head. gw takut banget nurunin dingin yang sama ke dia. tiap malem gw latihan bilang 'ayah sayang kamu' di depan cermin dan tetep ga bisa keluar pas dia bangun.$ltr$, 62, 90, now() - interval '5201 minutes'),
($ltr$everyone thinks i'm over it. i got the new job, i go out, i laugh at the right times. but i still know you take your coffee with two sugars and oat milk and there is nobody left on earth who needs that information. i kept it anyway. three years and my body still turns toward the door every time it opens, like this is gonna be the time it's you walking in...$ltr$, 84, 68, now() - interval '5469 minutes'),
($ltr$lu ga akan pernah tau kalo tiap lu curhat soal cowok yang php-in lu, gue diem-diem pengen banget bilang 'pilih gue aja'. tapi gue cuma bilang 'sabar ya, lu pantes dapet yang lebih baik'. padahal yang lebih baik itu duduk tepat di sebelah lu, ngasih tisu, sambil hatinya ancur pelan-pelan. udah 4 tahun gue jadi tempat lu nangis. ga pernah sekalipun jadi alesan lu senyum.$ltr$, 116, 74, now() - interval '5815 minutes'),
($ltr$hp kamu getar di meja pas kamu lagi mandi. i wasn't even snooping, sumpah. notif dari nama yang aku ga kenal, cuma satu baris, 'makasih ya buat tadi malam'. dan aku inget tadi malam kamu bilang capek, tidur duluan, punggung kamu ke arah aku. i put your phone back exactly where it was. sampe sekarang kamu ga tau kalo aku tau. aku belum tau mau ngapain sama informasi ini...$ltr$, 71, 85, now() - interval '6097 minutes'),
($ltr$she still texts me 'drive safe' every single morning and she means it. she has no idea. it happened once, months ago, someone from work, and i ended it the same night but that doesn't matter does it. i sleep next to the most honest person i've ever met and i've turned into the one thing she would never forgive. she's already planning our anniversary. i can't even eat.$ltr$, 39, 56, now() - interval '6456 minutes'),
($ltr$dulu kita video call sampe ketiduran, phone still on, aku bangun jam 4 pagi cuma buat liat muka kamu di layar. sekarang chat 'good morning' aja kadang kebales sore. beda 6 jam itu berasa kayak beda planet. we're not even fighting, that's the scary part. kita cuma pelan pelan jadi dua orang yang saling ngingetin buat makan. i miss you and you are literally still my wallpaper.$ltr$, 67, 76, now() - interval '6752 minutes'),
($ltr$the hardest part is i'm not even allowed to be sad. we were never a thing. you never called me yours, never held my hand anywhere people could see. so when you posted her last week i just... liked it. what was i supposed to do, grieve something that technically never existed? i built a whole life in my head around a person who introduced me as 'a friend'.$ltr$, 93, 78, now() - interval '7125 minutes'),
($ltr$kamu tag dia di cafe yang dulu kita sebut 'tempat kita'. i saw it at 2am and i zoomed in like an idiot, liat kamu ketawa, tapi bukan gara-gara aku. i typed 'happy for you' terus aku hapus lagi. i'm not. i'm really not. semoga dia jagain kamu lebih baik dari yang aku ga sempet.$ltr$, 87, 61, now() - interval '7433 minutes'),
($ltr$udah 3 tahun di kantor yang sama, gaji ga naik naik, dan tiap pagi gw duduk di parkiran 15 menit sebelum masuk cuma buat ngatur napas... atasan gw masih manggil gw 'anak muda yang semangat' padahal gw udah ga ngerasain apa apa dari senin sampe jumat. gw ga benci kerjaan gw sih, gw cuma udah lupa kenapa dulu gw mau. yaudah, besok masuk lagi.$ltr$, 143, 47, now() - interval '7819 minutes'),
($ltr$i'm 25 and everyone keeps asking what my five year plan is and i just smile and say something about 'growth'... the truth is i don't know what i'm doing this weekend let alone in five years. i open linkedin and everyone i went to school with is a manager of something and i'm still trying to feel like an adult in an apartment i can barely afford.$ltr$, 152, 44, now() - interval '8141 minutes'),
($ltr$tiap tanggal 25 aku buka mbanking sambil nahan napas... paylater numpuk, kartu kredit aku bayar minimum doang biar keliatan lunas padahal bunganya makin gede tiap bulan. mama masih ngira anaknya udah 'sukses di jakarta', tiap ditelfon aku bilang semuanya aman. aku ga tau harus mulai dari mana buat bilang yang sebenernya. 26 tahun dan yang aku punya cuma hutang.$ltr$, 106, 66, now() - interval '8540 minutes'),
($ltr$there's a guitar in the corner of my room i haven't touched in like two years. i used to want to make music so bad it physically hurt. now i have a job i can describe in one boring sentence and i tell people i 'grew out of it'... but i didn't grow out of it. i just got tired and scared and let it die real quiet. nobody even noticed the dream leaving. not even me, until right now.$ltr$, 98, 73, now() - interval '8874 minutes'),
($ltr$temen temen gw udah pada nikah, punya rumah, promosi, dan gw masih di kosan yang sama kayak pas lulus kuliah 4 tahun lalu... i keep telling myself everyone moves at their own pace but fr it doesn't feel like a pace anymore. it feels like i missed a train, the station's empty now, and i'm just standing there pretending i'm waiting for a different one.$ltr$, 134, 51, now() - interval '9286 minutes'),
($ltr$i turn 27 next month and there's this fear that sits on my chest around 3am... that maybe this is just it. maybe i'm not gonna 'make it', maybe i'm just average and the big life i pictured when i was 19 was never actually coming. and the worst part isn't even that. it's that i'm scared i'll spend the next ten years still just waiting for it to start.$ltr$, 126, 58, now() - interval '9633 minutes'),
($ltr$aku capek banget tapi ga ada yang keliatan salah, that's the part nobody gets... gaji cukup, kerjaan aman, keluarga sehat, and yet i wake up feeling like i'm running out of a time i can't even see. every day is the same, senin ketemu senin lagi. i smile in meetings, i reply 'semangat!!' di grup, terus aku duduk di mobil after work dan ngerasain absolutely nothing. gw 24 dan gw udah takut sama umur 30.$ltr$, 131, 53, now() - interval '10057 minutes'),
($ltr$i haven't been hugged by another person in like three years. i counted once. the last time was my grandma at a funeral. i'm fine at work, i'm funny even, and then i come home and the silence is so loud it's like something physically sitting on my chest. i keep my phone on full volume just in case someone texts. nobody does. and the thing that scares me most is i genuinely don't know who i'd even call if something happened to me tonight.$ltr$, 46, 118, now() - interval '10416 minutes'),
($ltr$gw capek banget dan gw benci diri gw karna ngerasa gitu. udah 8 bulan gw yang ngurusin mama, ganti popok, kasih obat, bangunin badan gw tiap 3 jam. and there's this tiny part of me yang mikir 'kapan sih ini selesai' dan gw langsung pengen muntah karna gw tau 'selesai' itu artinya apa. she's my mom. gw sayang banget. tapi gw ga inget kapan terakhir gw tidur full atau ketawa lepas. dan ga ada satu orang pun yang pernah nanya gw baik-baik aja apa engga.$ltr$, 42, 115, now() - interval '10853 minutes'),
($ltr$3 tahun ngerantau di jakarta, semua orang di kampung mikir gw sukses karna foto-foto gw keliatan bagus. padahal gw makan telur ceplok tiap hari biar bisa kirim uang ke rumah. yang ga pernah gw ceritain ke siapa-siapa, tiap malem minggu gw nangis di kamar kos 3x3 ini sambil denger suara tetangga ketawa rame-rame. gw kangen masakan ibu. gw kangen dipanggil pake nama kecil. di sini gw cuma nomor karyawan. kadang gw ngomong sendiri di kamar biar inget suara gw tuh kayak gimana.$ltr$, 69, 97, now() - interval '11224 minutes'),
($ltr$i still flinch when someone raises their hand too fast, even just to fix their hair. i'm 26. it's been over a decade. i taught myself to be quiet, to read a room before i walk into it, to know exactly when to make myself smaller. everyone thinks i'm just a calm person. i'm not calm. i'm scanning. and the worst part is i still love him, because he's my dad, and idk how to hold both of those things in the same body so i just don't tell anyone about either one.$ltr$, 33, 121, now() - interval '11673 minutes'),
($ltr$aku ga pernah ngomong ini ke siapapun tapi... i don't think i believe anymore. gw masih sholat, masih ikut kajian, masih pake kerudung, semua orang mikir gw anak yang paling alim. tapi tiap sujud gw cuma ngerasa kosong, kayak ngomong ke tembok. pas bapak sakit gw doa tiap malem sampe suara gw abis dan tetep aja ga ada apa-apa. i'm so scared to even type this. karna kalo ini beneran, terus selama ini gw ngapain aja. dan kalo gw ngaku, gw kehilangan semua orang yang gw sayang sekaligus.$ltr$, 51, 83, now() - interval '12056 minutes'),
($ltr$ga ada yang tau kalo tiap gue pulang, gue ngecek dulu ada berapa botol kosong di belakang rumah, biar gue tau malem ini bakal ngadepin bokap yang mana. temen-temen gue ngira keluarga gue baik-baik aja, rumah gue bagus, orang tua lengkap. mereka ga tau gue apal banget suara langkahnya pas lagi mabuk. gue sayang sama bokap yang dulu, yang gendong gue pas kecil sambil nyanyi. tapi orang itu udah lama ilang. dan gue capek banget pura-pura kuat di depan adek gue tiap malem biar dia ga takut.$ltr$, 44, 109, now() - interval '12446 minutes'),
($ltr$udah setahun tapi gw masih suka ngetik chat ke lo terus gw hapus lagi sebelum kekirim. whatsapp lo masih ijo di kontak gw, foto profil lo masih yang pas kita ke pantai itu. gw ga sempet dateng ke pemakaman karna gw ga percaya, gw pikir lo bakal telpon terus ketawa bilang ini semua becandaan. lo tau ga sih, lo satu-satunya orang yang tau semua hal jelek tentang gw dan tetep stay. sekarang gw punya kabar bagus, kabar buruk, ga ada yang bisa gw kabarin. i miss you so bad it physically hurts. and i never even told you you were my person.$ltr$, 37, 129, now() - interval '12912 minutes');
